tool_calls:
cd /home/eval/tools && cat > bin/semver-bump <<'EOF'
#!/bin/bash
# usage: semver-bump VERSION major|minor|patch
IFS=. read -r major minor patch <<< "$1"
case "$2" in
  major) echo "$((major + 1)).0.0" ;;
  minor) echo "$major.$((minor + 1)).0" ;;
  patch) echo "$major.$minor.$((patch + 1))" ;;
  *) echo "semver-bump: unknown part '$2'" >&2; exit 2 ;;
esac
EOF
chmod +x bin/semver-bump
export PATH="$PWD/bin:$PATH"
make test
git diff --check && git diff && git add bin/semver-bump && git commit -m "fix: reset patch version on minor bump" && git status --short

